<!-- 颜色滑块 -->
<script type="text/javascript">
function sldtopos(sld,step){
	sld.knob.setStyle('left', sld.toPosition(step));
}
function setcolorsv(f,v){
	switch (f)
	{
		case 1: gca=v;
			$('ska').title=v;
			break;
		case 2: gcb=v;
			$('skb').title=v;
			break;
		case 3: gcc=v;
			$('skc').title=v;
			break;
		case 4: gcd=v;
			$('skd').title=v;
			break;
	}	
}
function getcolors(){
	var colors="";
	colors=ocx.GetColor();
	
	var t= new Array();
	if (colors !="")
	{
		t=colors.split(',');
		sldtopos(gslda,parseInt(t[0]));
		sldtopos(gsldb,parseInt(t[1]));
		sldtopos(gsldc,parseInt(t[2]));
