	{
		chr1 = input.charCodeAt(i++);
		chr2 = input.charCodeAt(i++);
		chr3 = input.charCodeAt(i++);
		enc1 = chr1 >> 2;
		enc2 = ((chr1 & 3) << 4) | (chr2 >> 4);
		enc3 = ((chr2 & 15) << 2) | (chr3 >> 6);
		enc4 = chr3 & 63;
		
		if (isNaN(chr2)) 
		{
			enc3 = enc4 = 64;
		} 
		else if (isNaN(chr3)) 
		{
			enc4 = 64;
		}
		output = output + keyStr.charAt(enc1) + keyStr.charAt(enc2) + keyStr.charAt(enc3) + keyStr.charAt(enc4);
	}
	return output;
}

function utf8_encode (string) 
{
	string = string.replace(/\r\n/g,"\n");
	var utftext = "";
	
	for (var n = 0; n < string.length; n++) 
	{
		var c = string.charCodeAt(n);
		if (c < 128) 
		{
			utftext += String.fromCharCode(c);
		}
		else if((c > 127) && (c < 2048)) 
		{
			utftext += String.fromCharCode((c >> 6) | 192);
			utftext += String.fromCharCode((c & 63) | 128);
		}
		else
		{
			utftext += String.fromCharCode((c >> 12) | 224);
			utftext += String.fromCharCode(((c >> 6) & 63) | 128);
			utftext += String.fromCharCode((c & 63) | 128);
		}
	}	
	return utftext;
}

function PCWin(event)
{
	if (event.keyCode == 13)
	{
		PCSubWin();
	}
}

function PCSubWin()
{	
	if (isLocked == true)
	{
		return ;
	}
		
	var auth;
	var password = $("pcPassword").value;
	var userName = $("userName").value;
	auth = "Basic "+Base64Encoding(userName+":"+password);
	document.cookie = "Authorization=" + auth;
	window.location.reload();
}

function deleteCookie(name) 
{ 
    var LargeExpDate = new Date ();
    document.cookie = name + "=; expires=" +LargeExpDate.toGMTString(); 
}

function $(id)
{
	return document.getElementById(id);
}

function lockWeb(bLock)
{
	$("userName").disabled = bLock;
	$("pcPassword").disabled = bLock;
}

function resize()
{
	bodyObj = document.body;
	bodyObj.style["width"] = (document.documentElement.clientWidth < 1000 ? 1000 : document.documentElement.clientWidth) + "px";
}

function pageLoad()
{
	resize();
	window.onresize = resize;
	window.setInterval("document.getElementById('iRefresh').src='/img/login/top_bg.jpg?' + (+new Date())", 500000); 
	var tip = $("tip"), tipStr="", note = $("note");
	var unLi = $("unLi");
	var pwLi = $("pwLi");
	var userName = $("userName");
	var pcPassword = $("pcPassword");
	
	deleteCookie("Authorization");
	
	pcPassword.onfocus = function()
	{
		pwLi.style.background = "url(../img/login/inputSelect.png) no-repeat";
	};
	
	pcPassword.onblur = function()
	{
		pwLi.style.background = "url(../img/login/input.png) no-repeat";
	};
	   
	userName.onfocus = function()
	{
		unLi.style.background = "url(../img/login/inputSelect.png) no-repeat";
	};
	   
	userName.onblur = function()
	{
		unLi.style.background = "url(../img/login/input.png) no-repeat";
	};
	
	try { 
		if (modelName) 
		{
			document.title = modelName; 
			$("mnum").innerHTML = "Model No. " + modelName;		
		} 
		if(modelDesc)
		{
			$("mname").innerHTML = modelDesc;
		}
	}catch(e) {}
	
	if (authTimes > 0)
	{
		$("note").innerHTML = "NOTE:";
		$("tip").innerHTML = "The username or password is incorrect, please try again.";
	}	
	
	if (authTimes >= 5)
	{
		isLocked = true;
		lockWeb(true);
		$("note").innerHTML = "NOTE:";
		tipStr = "You have exceeded five login attempts. Please try again in ";
		count = 600 - forbidTime;
		$("tip").innerHTML = tipStr + count + "s.";		
		window.setTimeout(function()
		{
			if (count < 1)
			{
				$("note").innerHTML = "";
				$("tip").innerHTML = "";
				isLocked = false;
				lockWeb(false);
				userName.focus();
				deleteCookie("Authorization");
				window.location.reload();
				return ;
			}
			count--;
			$("tip").innerHTML = tipStr + count + "s.";
			window.setTimeout(arguments.callee, 1000);
		}, 1000);
	}
	else
	{
		userName.focus();
	}
}
