		}
		
		forbidAdminLogin = 0;
		authTimes = 0;
				if (INCLUDE_FORBIDDEN_OLD_PWD) {
			pcPassword.focus();
			pcPassword.select();
		}
		else{
			userName.focus();
			userName.select();
		}
		lockWeb(true);
		return;
	}		
	
	if (authTimes > 0)
	{
		if (localString)
		{
			$.id("note").innerHTML = localString[lang].NOTE;
			$.id("tip").innerHTML = localString[lang].TIP_ERROR;
		}
		else{
			$.id("note").innerHTML = "NOTE:";
			$.id("tip").innerHTML = "The username or password is incorrect, please try again.";
		}
	}	
	
	if (authTimes >= 10)
	{
		isLocked = true;
		lockWeb(true);
		count = 7200 - forbidTime;
		if (localString)
		{
			$.id("note").innerHTML = localString[lang].NOTE;
			tipStr = localString[lang].TIP_EXCE1;
			$.id("tip").innerHTML = tipStr + count + localString[lang].TIP_EXCE2;;		
		}
		else
		{
			$.id("note").innerHTML = "NOTE：";
			tipStr = "You have exceeded ten attempts. Please try again in ";
			$.id("tip").innerHTML = tipStr + count + "s.";		
		}

		window.setTimeout(function()
		{
			if (count < 1)
			{
				$.id("note").innerHTML = "";
				$.id("tip").innerHTML = "";
				isLocked = false;
				lockWeb(false);
						if (INCLUDE_FORBIDDEN_OLD_PWD) {
							pcPassword.focus();
						} else {
							userName.focus();
						}
				deleteCookie("Authorization");
				window.location.reload();
				return ;
			}
			count--;
			if (localString)
			{
				$.id("tip").innerHTML = tipStr + count + localString[lang].TIP_EXCE2;	
			}
			else{
				$.id("tip").innerHTML = tipStr + count + "s.";
			}
			window.setTimeout(arguments.callee, 1000);
		}, 1000);
			} else {
				pcPassword.focus();
			}
			if (INCLUDE_FORBIDDEN_OLD_PWD) {
				pcPassword.focus();
				pcPassword.select();
	}
	else{
		userName.focus();
		userName.select();
	}
