function resize(){
	//var hmbb;
	//var wmbb;
	var wwidth =document.documentElement.clientWidth;
	var wheight=document.documentElement.clientHeight;
	if (wheight<670) wheight=670;


    var hma=55;

    var hmbb_a=36;
    var hmbb_b=52;

    var hmba_a=43;
    var hmba_b=10;
    var hmba_c=52;

    var hmbc_a=43;
    var hmbc_b=10;
    var hmbc_c=52;
	var hmbc_d=20;

    var wmba=157;
    var wmbc=157;

    var hmbb_pla=wheight-hma-hmbb_a-hmbb_b + hmbc_d + 1;
    var hmba_main=wheight-hma-hmba_a-hmba_b-hmba_c + hmbc_d;
    var hmbc_main=wheight-hma-hmbc_a-hmbc_b-hmbc_c + hmbc_d;

